import java.util.Arrays;
import java.util.Objects;

public final class BubbleSort {
    private static final String NULL_NUMBERS_MESSAGE = "numbers must not be null";

    private BubbleSort() {
    }

    public static int[] sortedCopy(int[] numbers) {
        int[] source = requireNumbers(numbers);
        int[] copy = Arrays.copyOf(source, source.length);
        sort(copy);
        return copy;
    }

    public static void sort(int[] numbers) {
        int[] sortableNumbers = requireNumbers(numbers);

        if (sortableNumbers.length < 2) {
            return;
        }

        int lastUnsortedIndex = sortableNumbers.length - 1;
        while (lastUnsortedIndex > 0) {
            lastUnsortedIndex = moveLargestValueToBoundary(sortableNumbers, lastUnsortedIndex);
        }
    }

    private static int[] requireNumbers(int[] numbers) {
        return Objects.requireNonNull(numbers, NULL_NUMBERS_MESSAGE);
    }

    private static int moveLargestValueToBoundary(int[] numbers, int boundaryIndex) {
        int lastSwapIndex = 0;

        for (int currentIndex = 0; currentIndex < boundaryIndex; currentIndex++) {
            int nextIndex = currentIndex + 1;

            if (!isOutOfOrder(numbers, currentIndex, nextIndex)) {
                continue;
            }

            swap(numbers, currentIndex, nextIndex);
            lastSwapIndex = currentIndex;
        }

        return lastSwapIndex;
    }

    private static boolean isOutOfOrder(int[] numbers, int firstIndex, int secondIndex) {
        return numbers[firstIndex] > numbers[secondIndex];
    }

    private static void swap(int[] numbers, int firstIndex, int secondIndex) {
        int temp = numbers[firstIndex];
        numbers[firstIndex] = numbers[secondIndex];
        numbers[secondIndex] = temp;
    }
}

import java.util.Arrays;

public final class BubbleSortTest {
    private BubbleSortTest() {
    }

    public static void main(String[] args) {
        runAllTests();
        System.out.println("All tests passed.");
    }

    private static void runAllTests() {
        sortsInPlace();
        returnsSortedCopy();
        handlesDuplicateValues();
        handlesEmptyArray();
        rejectsNullSortInput();
        rejectsNullCopyInput();
    }

    private static void sortsInPlace() {
        int[] numbers = {5, 1, 4, 2, 8};

        BubbleSort.sort(numbers);

        assertArrayEquals(new int[] {1, 2, 4, 5, 8}, numbers);
    }

    private static void returnsSortedCopy() {
        int[] numbers = {3, 2, 1};

        int[] sortedNumbers = BubbleSort.sortedCopy(numbers);

        assertArrayEquals(new int[] {1, 2, 3}, sortedNumbers);
        assertArrayEquals(new int[] {3, 2, 1}, numbers);
    }

    private static void handlesDuplicateValues() {
        int[] numbers = {4, 2, 4, 1, 2};

        BubbleSort.sort(numbers);

        assertArrayEquals(new int[] {1, 2, 2, 4, 4}, numbers);
    }

    private static void handlesEmptyArray() {
        int[] numbers = {};

        BubbleSort.sort(numbers);

        assertArrayEquals(new int[] {}, numbers);
    }

    private static void rejectsNullSortInput() {
        assertThrows(NullPointerException.class, () -> BubbleSort.sort(null));
    }

    private static void rejectsNullCopyInput() {
        assertThrows(NullPointerException.class, () -> BubbleSort.sortedCopy(null));
    }

    private static void assertThrows(Class<? extends Throwable> expectedType, ThrowingRunnable action) {
        assertThrows(expectedType, () -> {
            action.run();
            return null;
        });
    }

    private static void assertThrows(Class<? extends Throwable> expectedType, ThrowingSupplier<?> action) {
        try {
            action.get();
        } catch (Throwable exception) {
            if (expectedType.isInstance(exception)) {
                return;
            }

            throw new AssertionError(
                    "Expected " + expectedType.getSimpleName()
                            + " but got " + exception.getClass().getSimpleName(),
                    exception);
        }

        throw new AssertionError("Expected " + expectedType.getSimpleName() + " to be thrown.");
    }

    private static void assertArrayEquals(int[] expected, int[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                    "Expected " + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    @FunctionalInterface
    private interface ThrowingRunnable {
        void run() throws Throwable;
    }

    @FunctionalInterface
    private interface ThrowingSupplier<T> {
        T get() throws Throwable;
    }
}

